// Generates lib/showcase/generated/example_sources.g.dart: the text of every
// file under lib/examples/, so the code shown next to a live example is the
// code that runs. Run from example/:
//
//   dart run tool/gen_example_sources.dart
//
// A test (test/example_sources_test.dart) fails when the committed file is out
// of date, so a snippet cannot drift from its example.
import 'dart:io';

const examplesDir = 'lib/examples';
const outputFile = 'lib/showcase/generated/example_sources.g.dart';

/// The generated file's text for the files currently under [examplesDir].
String generate() {
  final files = Directory(examplesDir)
      .listSync(recursive: true)
      .whereType<File>()
      .where((f) => f.path.endsWith('.dart'))
      .toList()
    ..sort((a, b) => a.path.compareTo(b.path));

  final buffer = StringBuffer()
    ..writeln('// GENERATED by tool/gen_example_sources.dart. Do not edit.')
    ..writeln(
        '// ignore_for_file: prefer_single_quotes, lines_longer_than_80_chars')
    ..writeln()
    ..writeln('/// The source of each example, by path under lib/examples/.')
    ..writeln('const Map<String, String> exampleSources = {');
  for (final file in files) {
    final key =
        file.path.substring(examplesDir.length + 1).replaceAll(r'\', '/');
    final body = displayText(file.readAsStringSync());
    if (body.contains("'''")) {
      throw StateError("$key contains ''' which the generator cannot embed");
    }
    buffer.writeln("  '$key': r'''$body''',");
  }
  buffer.writeln('};');
  return buffer.toString();
}

/// What to show: the file without its import lines and the blank lines after
/// them, and without the trailing newline.
String displayText(String source) {
  final lines = source.split('\n');
  var i = 0;
  while (i < lines.length &&
      (lines[i].startsWith('import ') || lines[i].trim().isEmpty)) {
    i++;
  }
  return lines.sublist(i).join('\n').trimRight();
}

void main() {
  File(outputFile)
    ..createSync(recursive: true)
    ..writeAsStringSync(generate());
  stdout.writeln('Wrote $outputFile');
}
